import CoreGraphics
import Foundation

/// Explicit per-terrain frame atlas for the floor spritesheet.
///
/// Each terrain id maps to a pixel rect tightly fitted to that sprite alone.
/// Frames are generated by claiming content top-to-bottom so a tile's south tip
/// is not absorbed into the cell below (which caused “top corner of the frame
/// above” artifacts with a naive grid AABB).
nonisolated struct FloorAtlas: Codable, Equatable, Sendable {
    var meta: Meta
    var frames: [String: Frame]

    struct Meta: Codable, Equatable, Sendable {
        var size: Size
        var durationS: Double

        enum CodingKeys: String, CodingKey {
            case size
            case durationS = "duration_s"
        }

        init(size: Size, durationS: Double = 0) {
            self.size = size
            self.durationS = durationS
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            size = try container.decode(Size.self, forKey: .size)
            durationS = try container.decodeIfPresent(Double.self, forKey: .durationS) ?? 0
        }
    }

    struct Size: Codable, Equatable, Sendable {
        var w: Int
        var h: Int
    }

    struct Frame: Codable, Equatable, Sendable {
        var x: Int
        var y: Int
        var w: Int
        var h: Int
    }

    /// Pixel rect for a named terrain frame (image top-left origin).
    func frameRect(named id: String) -> CGRect? {
        guard let frame = frames[id], frame.w > 0, frame.h > 0 else { return nil }
        return CGRect(x: frame.x, y: frame.y, width: frame.w, height: frame.h)
    }

    static func decode(from data: Data) throws -> FloorAtlas {
        try JSONDecoder().decode(FloorAtlas.self, from: data)
    }
}
